#!/usr/bin/env python3
"""Compute deterministic ground truth for CSX-255_Q2."""

from __future__ import annotations

import json
from collections import Counter
from datetime import date
from pathlib import Path
from statistics import mean


TASK_ID = "CSX-255_Q2"
EVENT_ID = "CSX-255"
TASK_TYPE = "numeric"
TARGET_FAMILY = "freddy_rainfall_surface_threshold_ledger"

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_003_Locked_event_anchor_Cyclone_Freddy_floods_landslides_and_cholera_risk.json",
    "data/physical_hazard/physical_hazard_003_ERA5-Land_hourly_aggregate_stats.json",
    "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_005_CHIRPS_daily_event_accumulated_precipitation.json",
    "data/remote_sensing/remote_sensing_003_Google_Satellite_Embedding_annual_cosine-change_stats.json",
    "data/physical_hazard/physical_hazard_006_Sentinel-2_SR_Harmonized_dNBR.json",
    "data/exposure_impact/exposure_impact_002_WorldPop_GP_100m_population_sum.json",
    "data/exposure_impact/exposure_impact_003_OpenStreetMap_Overpass_bounded_AOI_slice.json",
]



REASONING_DEPTH = {'evidence_weighting': 'The three precipitation products and rainfall score are decisive; surface metrics are peak-only checks and mapped features provide exposure context.', 'counterfactual_rejection': 'A surface-change-dominant reading fails because both area-mean surface checks fail even though peak surface checks pass.', 'uncertainty_or_scale_caveat': 'Mapped facility rates are exposure indicators and should not be interpreted as direct damage or service-disruption counts.'}


def attach_reasoning_depth(result):
    reasoning = dict(REASONING_DEPTH)
    primary = result.get("primary_gt")
    if isinstance(primary, dict):
        primary["reasoning_depth"] = reasoning
    guidance = result.get("answer_guidance")
    if isinstance(guidance, dict):
        guidance["reasoning_depth"] = reasoning
    key_values = result.get("key_values")
    if isinstance(key_values, dict):
        key_values["reasoning_depth"] = reasoning
    rubric = result.get("rubric")
    if isinstance(rubric, dict):
        criteria = rubric.get("criteria")
        if isinstance(criteria, list) and criteria:
            addition = " Full credit also requires the `reasoning_depth` object to identify decisive evidence, reject the main tempting simplification, and state a bounded uncertainty or scale caveat."
            last = criteria[-1]
            desc = last.get("description", "")
            if addition.strip() not in desc:
                last["description"] = (desc.rstrip() + addition).strip()
    return result

def repo_root() -> Path:
    return Path(__file__).resolve().parents[3]


def package_dir() -> Path:
    return repo_root() / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID


def read_json(relative_path: str) -> dict:
    with (package_dir() / relative_path).open("r", encoding="utf-8-sig") as handle:
        return json.load(handle)


def rounded(value: float, digits: int) -> float:
    return round(float(value), digits)


def inclusive_days(start_text: str, end_text: str) -> int:
    start = date.fromisoformat(start_text)
    end = date.fromisoformat(end_text)
    return (end - start).days + 1


def summarize_osm(elements: list[dict]) -> dict:
    amenity_counts: Counter[str] = Counter()
    highway_counts: Counter[str] = Counter()
    building_count = 0

    for element in elements:
        tags = element.get("tags") or {}
        if "amenity" in tags:
            amenity_counts[str(tags["amenity"])] += 1
        if "highway" in tags:
            highway_counts[str(tags["highway"])] += 1
        if "building" in tags:
            building_count += 1

    facility_count = (
        amenity_counts.get("school", 0)
        + amenity_counts.get("hospital", 0)
        + amenity_counts.get("police", 0)
        + amenity_counts.get("fire_station", 0)
    )

    return {
        "osm_element_count": len(elements),
        "school_count": amenity_counts.get("school", 0),
        "hospital_count": amenity_counts.get("hospital", 0),
        "police_count": amenity_counts.get("police", 0),
        "fire_station_count": amenity_counts.get("fire_station", 0),
        "residential_road_count": highway_counts.get("residential", 0),
        "building_count": building_count,
        "facility_count": facility_count,
    }


def rubric() -> dict:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "Structured numeric ledger",
                "points": 3,
                "description": "Returns the requested compact JSON fields with numeric values, units implied by field names, and a final scalar score.",
            },
            {
                "name": "Precipitation arithmetic",
                "points": 5,
                "description": "Uses the three event-total mean and maximum precipitation values, computes the 39-day period, daily means, ensemble mean, and ensemble maximum within tolerance.",
            },
            {
                "name": "Threshold and score calculation",
                "points": 5,
                "description": "Applies the 75 mm mean-total and 150 mm maximum-total tests, derives mean_score, max_score, pass_share, and the weighted rainfall score of 84.06.",
            },
            {
                "name": "Surface-check ledger",
                "points": 3,
                "description": "Computes the area-mean and peak surface-check counts from AlphaEarth and Sentinel-2 values and assigns the peak_only_check role from those counts.",
            },
            {
                "name": "Mapped-feature rate",
                "points": 2,
                "description": "Counts schools, hospitals, police sites, fire stations, buildings, residential roads, and computes 14.95 facilities per 100,000 people.",
            },
            {
                "name": "Final label and concise synthesis",
                "points": 2,
                "description": "Pairs the numeric score with the rainfall_dominant_peak_surface_check label and gives a short calculation-based synthesis.",
            },
        ],
    }


def compute() -> dict:
    event = read_json("metadata/event.json")
    anchor = read_json(
        "data/event_reports/event_reports_003_Locked_event_anchor_Cyclone_Freddy_floods_landslides_and_cholera_risk.json"
    )
    era5 = read_json("data/physical_hazard/physical_hazard_003_ERA5-Land_hourly_aggregate_stats.json")
    gpm = read_json("data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json")
    chirps = read_json("data/physical_hazard/physical_hazard_005_CHIRPS_daily_event_accumulated_precipitation.json")
    alpha = read_json(
        "data/remote_sensing/remote_sensing_003_Google_Satellite_Embedding_annual_cosine-change_stats.json"
    )
    dnbr = read_json("data/physical_hazard/physical_hazard_006_Sentinel-2_SR_Harmonized_dNBR.json")
    population = read_json("data/exposure_impact/exposure_impact_002_WorldPop_GP_100m_population_sum.json")
    osm = read_json("data/exposure_impact/exposure_impact_003_OpenStreetMap_Overpass_bounded_AOI_slice.json")

    start_date = anchor["temporal_window"]["start_date"]
    end_date = anchor["temporal_window"]["end_date"]
    event_window_days = inclusive_days(start_date, end_date)

    product_raw = {
        "era5_land": {
            "mean_total_mm": era5["stats"]["precipitation_sum_mm_mean"],
            "max_total_mm": era5["stats"]["precipitation_sum_mm_max"],
        },
        "gpm_imerg": {
            "mean_total_mm": gpm["stats"]["gpm_event_precip_mm_mean"],
            "max_total_mm": gpm["stats"]["gpm_event_precip_mm_max"],
        },
        "chirps": {
            "mean_total_mm": chirps["stats"]["chirps_event_precip_mm_mean"],
            "max_total_mm": chirps["stats"]["chirps_event_precip_mm_max"],
        },
    }

    product_rows = {}
    for name, values in product_raw.items():
        mean_total = values["mean_total_mm"]
        max_total = values["max_total_mm"]
        product_rows[name] = {
            "mean_total_mm": rounded(mean_total, 3),
            "max_total_mm": rounded(max_total, 3),
            "mean_daily_mm": rounded(mean_total / event_window_days, 2),
            "mean_ge_75mm": mean_total >= 75.0,
            "max_ge_150mm": max_total >= 150.0,
        }

    mean_totals = [values["mean_total_mm"] for values in product_raw.values()]
    max_totals = [values["max_total_mm"] for values in product_raw.values()]
    mean_passes = sum(value >= 75.0 for value in mean_totals)
    max_passes = sum(value >= 150.0 for value in max_totals)
    pass_share = (mean_passes + max_passes) / 6.0
    mean_score = mean(min(value / 100.0, 1.0) for value in mean_totals)
    max_score = mean(min(value / 150.0, 1.0) for value in max_totals)
    rainfall_score = 100.0 * (0.55 * mean_score + 0.35 * max_score + 0.10 * pass_share)

    alpha_stats = alpha["stats"]
    dnbr_stats = dnbr["stats"]
    alpha_mean = alpha_stats["alphaearth_1_minus_cosine_mean"]
    alpha_max = alpha_stats["alphaearth_1_minus_cosine_max"]
    dnbr_mean = dnbr_stats["sentinel2_dnbr_mean"]
    dnbr_max = dnbr_stats["sentinel2_dnbr_max"]
    area_mean_passes = int(alpha_mean >= 0.10) + int(dnbr_mean >= 0.10)
    peak_passes = int(alpha_max >= 0.40) + int(dnbr_max >= 0.50)
    surface_role = "peak_only_check" if area_mean_passes == 0 and peak_passes > 0 else "area_mean_shift"

    population_sum = population["population_sum"]["population"]
    osm_summary = summarize_osm(osm.get("elements", []))
    facility_rate_per_100k = osm_summary["facility_count"] / (population_sum / 100000.0)
    facility_feature_share = osm_summary["facility_count"] / osm_summary["osm_element_count"]

    label = (
        "rainfall_dominant_peak_surface_check"
        if rainfall_score >= 70.0 and area_mean_passes == 0
        else "mixed_signal_calibration"
    )

    primary_gt = {
        "event_window_days": event_window_days,
        "precipitation_products": product_rows,
        "rainfall_ledger": {
            "ensemble_mean_total_mm": rounded(mean(mean_totals), 3),
            "ensemble_max_total_mm": rounded(max(max_totals), 3),
            "mean_score": rounded(mean_score, 5),
            "max_score": rounded(max_score, 5),
            "pass_share": rounded(pass_share, 5),
            "rainfall_score": rounded(rainfall_score, 2),
        },
        "surface_check": {
            "area_mean_passes": area_mean_passes,
            "peak_passes": peak_passes,
            "surface_role": surface_role,
        },
        "mapped_feature_ledger": {
            "facility_count": osm_summary["facility_count"],
            "facility_rate_per_100k": rounded(facility_rate_per_100k, 2),
        },
        "final_label": label,
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": TASK_TYPE,
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "rubric": rubric(),
        "event": {
            "package_id": EVENT_ID,
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_date_or_window": f"{start_date} to {end_date}",
            "location": anchor["spatial_window"]["location_text"],
        },
        "calculation_rule": {
            "event_window_days": event_window_days,
            "rainfall_score_formula": "100*(0.55*mean_score + 0.35*max_score + 0.10*pass_share)",
            "mean_score_formula": "mean(min(product_mean_total_mm/100,1))",
            "max_score_formula": "mean(min(product_max_total_mm/150,1))",
            "pass_share_formula": "(count(mean_total_mm>=75)+count(max_total_mm>=150))/6",
            "surface_role_rule": "peak_only_check when area_mean_passes=0 and peak_passes>0",
        },
        "key_values": {
            "event_window_days": event_window_days,
            "precipitation_products": product_rows,
            "ensemble_mean_total_mm": primary_gt["rainfall_ledger"]["ensemble_mean_total_mm"],
            "ensemble_max_total_mm": primary_gt["rainfall_ledger"]["ensemble_max_total_mm"],
            "mean_score": primary_gt["rainfall_ledger"]["mean_score"],
            "max_score": primary_gt["rainfall_ledger"]["max_score"],
            "pass_share": primary_gt["rainfall_ledger"]["pass_share"],
            "rainfall_score": primary_gt["rainfall_ledger"]["rainfall_score"],
            "alphaearth_mean_change": rounded(alpha_mean, 4),
            "alphaearth_max_change": rounded(alpha_max, 4),
            "sentinel2_mean_dnbr": rounded(dnbr_mean, 4),
            "sentinel2_max_dnbr": rounded(dnbr_max, 4),
            "area_mean_passes": area_mean_passes,
            "peak_passes": peak_passes,
            "surface_role": surface_role,
            "population_sum": rounded(population_sum, 3),
            "osm_summary": {
                **osm_summary,
                "facility_feature_share": rounded(facility_feature_share, 3),
                "facility_rate_per_100k": primary_gt["mapped_feature_ledger"]["facility_rate_per_100k"],
            },
        },
        "numeric_tolerances": {
            "rainfall_score": {"target": primary_gt["rainfall_ledger"]["rainfall_score"], "absolute_tolerance": 0.02},
            "ensemble_mean_total_mm": {"target": primary_gt["rainfall_ledger"]["ensemble_mean_total_mm"], "absolute_tolerance": 0.005},
            "ensemble_max_total_mm": {"target": primary_gt["rainfall_ledger"]["ensemble_max_total_mm"], "absolute_tolerance": 0.005},
            "facility_rate_per_100k": {
                "target": primary_gt["mapped_feature_ledger"]["facility_rate_per_100k"],
                "absolute_tolerance": 0.01,
            },
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
    }


def main() -> None:
    output_path = Path(__file__).resolve().parent / "computed_gt.json"
    result = compute()
    attach_reasoning_depth(result)
    output_path.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
